import{_ as s,a0 as p,w as r,s as i,I as n,x as e,a1 as a,A as l,ao as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const S=JSON.parse('{"title":"為何 Elementary OS 中使用 Pantheon 桌面 | LCTT x X-CMD","titleTemplate":false,"description":"為何 Elementary OS 中使用 Pantheon 桌面 | LCTT (201912) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"為何 Elementary OS 中使用 Pantheon 桌面 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"為何 Elementary OS 中使用 Pantheon 桌面 | LCTT (201912) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201912/20191203 Why use the Pantheon desktop for Linux Elementary OS","title":"為何 Elementary OS 中使用 Pantheon 桌面","tag":"201912","desc":""},"relativePath":"201912/20191203 Why use the Pantheon desktop for Linux Elementary OS.md","filePath":"[post].md"}'),h={name:"201912/20191203 Why use the Pantheon desktop for Linux Elementary OS.md"};function m(d,t,f,P,g,x){const o=p("Link");return r(),i("div",null,[t[23]||(t[23]=n("h1",{id:"為何-elementary-os-中使用-pantheon-桌面",tabindex:"-1"},[e("為何 Elementary OS 中使用 Pantheon 桌面 "),n("a",{class:"header-anchor",href:"#為何-elementary-os-中使用-pantheon-桌面","aria-label":"Permalink to “為何 Elementary OS 中使用 Pantheon 桌面”"},"​")],-1)),t[24]||(t[24]=n("blockquote",null,[n("p",null,"本文是 Linux 桌面特別系列的一部分。通過在 Elementary OS 上運行 Pantheon 桌面獲得廣受喜愛的 Mac OS 特性。")],-1)),t[25]||(t[25]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/201912/10/085342dfgngrpt6sgzl3af.jpg",alt:""})],-1)),n("p",null,[t[1]||(t[1]=e("你願意為 Linux 桌面支付 20 美元嗎？事實上，我會在下載自由軟件時選擇支付更多的錢！我這樣做的原因是開源是值得的。對於 ",-1)),a(o,{href:"https://elementary.io/"},{default:l(()=>[...t[0]||(t[0]=[e("Elementary OS",-1)])]),_:1}),t[2]||(t[2]=e(" 的拷貝，默認價格是 20 美元（你可以選擇 1 美元，如果你無法負擔，你甚至可以用 0 美元下載）。作為回報，你將獲得一個出色且精心製作的發行版，同時擁有它自己的 Pantheon 桌面設計。",-1))]),n("p",null,[t[5]||(t[5]=e("你可能會發現 Pantheon 已包含在軟件倉庫中，因為它是開源的，但你更可能需要下載並安裝 ",-1)),a(o,{href:"http://elementary.io"},{default:l(()=>[...t[3]||(t[3]=[e("Elementary",-1)])]),_:1}),t[6]||(t[6]=e(" Linux 才能體驗它。如果你還不準備在計算機上將 Elementary 作為主操作系統，那麼可以將其安裝到虛擬機中，例如 ",-1)),a(o,{href:"https://opensource.com/article/19/5/getting-started-gnome-boxes-virtualization"},{default:l(()=>[...t[4]||(t[4]=[e("GNOME Boxes",-1)])]),_:1}),t[7]||(t[7]=e(" 中。",-1))]),t[26]||(t[26]=u('<p>Pantheon 桌面整潔、吸引人，並且有許多用户希望在桌面中獲得的東西，但在普通的 Linux 桌面上卻無法獲得。</p><h3 id="pantheon-桌面之旅" tabindex="-1">Pantheon 桌面之旅 <a class="header-anchor" href="#pantheon-桌面之旅" aria-label="Permalink to “Pantheon 桌面之旅”">​</a></h3><p>乍一看，Pantheon 桌面看起來有點像 Cinnamon、Budgie 或 GNOME 3 的經典模式。但是，Pantheon 最令人興奮的功能是極小的接觸。它在你很少注意到的地方都表現出色，直到有一天這裏成為了你一天都會看的地方，並且會意識到它的工作方式確實改善了你的生活質量，更不用説讓你過得愉快多了。</p><p>最明顯的例子是“文件名高亮”。幾十年來，Mac OS 一直有一個廣受歡迎的功能，你可以高亮顯示重要文件的名稱。人們使用此功能作為快速視覺指示器，來告訴自己哪個文件是這幾個的“最佳”版本，或者哪個文件應該發送給朋友，或者哪個文件仍然需要處理。它們可以是任意顏色，可以表示用户想要的任何含義。最重要的是，它是引人注目的視覺元數據。</p><p>從 Mac OS 切換過來用户往往會在 GNOME 和 KDE 以及 Linux 提供的其它桌面裏懷念這個功能。Pantheon 悄悄地隨手解決了這個問題。</p><p><img src="https://opensource.com/sites/default/files/uploads/advent-pantheon-highlight.jpg" alt="A highlighted file in the Pantheon desktop" title="A highlighted file in the Pantheon desktop"></p><p>當然，那只是其中一個例子。Pantheon 有很多你直到用才會想到的小功能。</p><p>桌面精緻而吸引人，有所有其他很多桌面缺少的直觀組件。在許多方面，它充分吸取了其他桌面好的想法，並避免實現多餘的東西。</p><p><img src="https://opensource.com/sites/default/files/uploads/advent-pantheon.jpg" alt="Pantheon desktop on Elementary OS" title="Pantheon desktop on Elementary OS"></p><h3 id="自定義-pantheon-桌面" tabindex="-1">自定義 Pantheon 桌面 <a class="header-anchor" href="#自定義-pantheon-桌面" aria-label="Permalink to “自定義 Pantheon 桌面”">​</a></h3><p>Pantheon 桌面表達瞭如何操作計算機的清晰願景。這種設計的“問題”（至少在開源之外）是，一個人的偏好可能無法滿足另一個人的效率。</p><p>但它是開源的。它可以更改，任何不能改變的東西都可以被丟棄。Pantheon 絕對是針對特定用户羣的桌面，但是即使對於那些對桌面應該如何工作抱有自己期望的人，Pantheon 也會比初看上去更加靈活。許多內置設計都具有替代選項，當你無法根據自己的喜好進行調整時，你可以輕鬆選擇其他應用。主題引擎可確保你的替換應用看起來與桌面的其它部分和諧一致，而通常的 Linux 系統兼容性可確保你選擇的所有應用都能按預期相互配合。</p><p><img src="https://opensource.com/sites/default/files/uploads/advent-pantheon-pcmanfm.jpg" alt="Which one is the guest?" title="Which one is the guest?"></p><p>這些替代品，可使你事半功倍。</p><h3 id="受歡迎的補充" tabindex="-1">受歡迎的補充 <a class="header-anchor" href="#受歡迎的補充" aria-label="Permalink to “受歡迎的補充”">​</a></h3><p>撇開這個桌面的詞源不説，此桌面確實是許多 Linux 用户祈禱的答案（LCTT 譯註：Pantheon 的意思是“萬神廟”）。無論它是否是你的風格，Pantheon 桌面都是 Linux 用户體驗中重要且受歡迎的補充。自己嘗試一下，看看它是否是你一直期待的。</p><hr>',17)),n("p",null,[t[9]||(t[9]=e("via: ",-1)),a(o,{href:"https://opensource.com/article/19/12/pantheon-linux-desktop"},{default:l(()=>[...t[8]||(t[8]=[e("https://opensource.com/article/19/12/pantheon-linux-desktop",-1)])]),_:1})]),n("p",null,[t[14]||(t[14]=e("作者：",-1)),a(o,{href:"https://opensource.com/users/seth"},{default:l(()=>[...t[10]||(t[10]=[e("Seth Kenlon",-1)])]),_:1}),t[15]||(t[15]=e(" 選題：",-1)),a(o,{href:"https://github.com/lujun9972"},{default:l(()=>[...t[11]||(t[11]=[e("lujun9972",-1)])]),_:1}),t[16]||(t[16]=e(" 譯者：",-1)),a(o,{href:"https://github.com/geekpi"},{default:l(()=>[...t[12]||(t[12]=[e("geekpi",-1)])]),_:1}),t[17]||(t[17]=e(" 校對：",-1)),a(o,{href:"https://github.com/wxy"},{default:l(()=>[...t[13]||(t[13]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[20]||(t[20]=e("本文由 ",-1)),a(o,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[18]||(t[18]=[e("LCTT",-1)])]),_:1}),t[21]||(t[21]=e(" 原創編譯，",-1)),a(o,{href:"https://linux.cn/"},{default:l(()=>[...t[19]||(t[19]=[e("Linux中國",-1)])]),_:1}),t[22]||(t[22]=e(" 榮譽推出",-1))])])}const E=s(h,[["render",m]]);export{S as __pageData,E as default};
